  for (const [file, { path, size }] of held) {
    if (extname(file) === ".md") continue;
    const mirrored = held.get(sisterDocOf(file));
    if (mirrored === undefined && (size <= SISTER_DOC_TRIGGER_BYTES || waived.has(file))) continue;
